a:1:{s:55:"../../../src/Services/Activities/WorkStatusResolver.php";a:1:{i:0;O:49:"PHPStan\Dependency\ExportedNode\ExportedClassNode":10:{s:55:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀name";s:45:"Sigcon\Services\Activities\WorkStatusResolver";s:57:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀phpDoc";O:50:"PHPStan\Dependency\ExportedNode\ExportedPhpDocNode":4:{s:64:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀phpDocString";s:885:"/**
